from pathlib import Path
import json
base=Path('.')
manifest=json.loads((base/'out/review/scan006_crop_manifest.json').read_text())
crops={Path(x['filename']).stem.removeprefix('scan006_'):x for x in manifest}
changes=[]
def add(key,place,C,H,final,shows,conf,kind,crop,ac,ah,mh=False,con=True):
    ent=crops[crop]
    changes.append(dict(id=key,place=place,C=C,H=H,final=final,scan_shows=shows,confidence=conf,kind=kind,crop=ent['filename'],box=ent['original_box'],against_C=ac,against_H=ah,marked_in_H=mh,consequential=con))
